import { useCallback, useMemo, useState } from 'react';
import {
  createColumnHelper,
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type SortingState,
  useReactTable
} from '@tanstack/react-table';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { Pagination, Tooltip } from '@docs-front/ui';
import {
  Badge,
  TableBody,
  TableBodyRow,
  TableHeader,
  TableHeaderRow,
  useToast
} from '@bichon/ds';
import { FileText, SquarePen, Star } from 'lucide-react';

import {
  deleteProductFileInterest,
  deleteProductInterest,
  postProductFileInterest,
  postProductInterest
} from '@/api/products/mutation';
import { getProduct } from '@/api/products/query';
import { getProductsQueryOptions } from '@/query/options/products';
import type {
  GetProductsFilesResponse,
  ProductFilePathMapContents,
  ProductSummary
} from '@/schema/api/products/products';
import { getFileNameFromPath } from '@/utils/file/getFileNameFromPath';

import {
  TableViewport,
  TableFrame,
  StyledTable,
  StyledHeaderCell,
  StyledBodyCell,
  EmptyStateCell,
  EmptyStateText,
  DocumentNameText,
  DateText,
  TableFooter,
  InterestIconButton,
  FileIcon,
  DraftIconWrapper,
  SelectedTableBodyRow,
  DocumentNameCellContent,
  DocumentNameMeta
} from '@/routes/_authenticated/f/upload/-components/ExistingDocumentsTable/ExistingDocumentsTable.style';

// --- 통합 Row 타입 ---

export interface UnifiedDocumentRow {
  sourceType: 'export' | 'draftProduct' | 'draftExport';
  id: string;
  document?: ProductFilePathMapContents;
  isInterested: boolean;
  status: ProductFilePathMapContents['status'] | ProductSummary['generationStatus'];
  /** 통합 문서명 (파일: 파일명, product 초안: 아이템명) */
  documentName: string;
  createdAt: string;
  createdAtTimestamp: number;
}

export type SelectedDocumentInfo =
  | { type: 'export'; document: ProductFilePathMapContents }
  | {
      type: 'draftProduct';
      product: { id: string; itemName: string | null; content: string };
    }
  | { type: 'draftExport'; document: ProductFilePathMapContents };

interface ExistingDocumentsTableProps {
  exportDocuments: ProductFilePathMapContents[];
  draftExportDocuments: ProductFilePathMapContents[];
  draftProducts: ProductSummary[];
  /** 현재 선택된 문서 (행 하이라이트 + 버튼 텍스트 변경) */
  selectedDocument: SelectedDocumentInfo | null;
  onUpload: (info: SelectedDocumentInfo | null) => void;
}

interface ColumnMeta {
  width?: string;
  align?: 'left' | 'center' | 'right';
  headerAlign?: 'left' | 'center' | 'right';
}

const PAGE_SIZE = 10;

const parseDocumentName = (filePath: string | null): string => {
  const fullFileName = getFileNameFromPath(filePath);
  if (!fullFileName) return '-';
  return fullFileName.replace(/\.[^/.]+$/, '') || fullFileName;
};

const formatCreatedAt = (raw: string): string => {
  const date = new Date(raw);
  if (isNaN(date.getTime())) return raw;
  const yy = String(date.getFullYear()).slice(-2);
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const hh = String(date.getHours()).padStart(2, '0');
  const min = String(date.getMinutes()).padStart(2, '0');
  return `${yy}.${mm}.${dd} ${hh}:${min}`;
};

const parseSortableTimestamp = (value?: string): number => {
  if (!value) return 0;

  const parsed = Date.parse(value);
  return Number.isNaN(parsed) ? 0 : parsed;
};

const getColumnMeta = (meta: unknown): ColumnMeta =>
  typeof meta === 'object' && meta !== null ? (meta as ColumnMeta) : {};

const isSelectableRow = (row: UnifiedDocumentRow): boolean =>
  row.status === 'COMPLETED';

const getProcessingTooltip = (row: UnifiedDocumentRow): string =>
  row.sourceType === 'draftProduct' ? '초안 생성중' : '문서 생성중';

const columnHelper = createColumnHelper<UnifiedDocumentRow>();

export default function ExistingDocumentsTable({
  exportDocuments,
  draftExportDocuments,
  draftProducts,
  selectedDocument,
  onUpload
}: ExistingDocumentsTableProps) {
  const queryClient = useQueryClient();
  const toast = useToast();
  const productsQueryOptions = getProductsQueryOptions();
  const productsQueryKey = productsQueryOptions.queryKey;
  const productsFilesQueryKey = ['productsFiles'] as const;
  const [pageIndex, setPageIndex] = useState(0);
  const [pendingInterestRowKey, setPendingInterestRowKey] = useState<string | null>(null);

  // --- 관심 토글 ---
  const toggleInterestMutation = useMutation({
    mutationFn: ({
      sourceType,
      documentId,
      isInterested
    }: {
      sourceType: UnifiedDocumentRow['sourceType'];
      documentId: string;
      isInterested: boolean;
    }) =>
      sourceType === 'draftProduct'
        ? isInterested
          ? deleteProductInterest(documentId)
          : postProductInterest(documentId)
        : isInterested
        ? deleteProductFileInterest(documentId)
        : postProductFileInterest(documentId),
    onMutate: ({ sourceType, documentId }) => {
      setPendingInterestRowKey(`${sourceType}-${documentId}`);
    },
    onSuccess: (response, { sourceType, documentId }) => {
      if (sourceType === 'draftProduct') {
        queryClient.setQueryData<ProductSummary[]>(productsQueryKey, (previousProducts) =>
          previousProducts?.map((product) =>
            product.id === documentId
              ? { ...product, isInterested: response.isInterested }
              : product
          ) ?? previousProducts
        );

        return;
      }

      queryClient.setQueriesData<GetProductsFilesResponse>(
        { queryKey: productsFilesQueryKey },
        (previousExports) => {
          const exportsPage = previousExports?.data?.exports;
          if (!previousExports || !exportsPage) {
            return previousExports;
          }

          return {
            ...previousExports,
            data: {
              ...previousExports.data,
              exports: {
                ...exportsPage,
                content: exportsPage.content.map((document) =>
                  document.productFileId === documentId
                    ? { ...document, isInterested: response.isInterested }
                    : document
                )
              }
            }
          };
        }
      );
    },
    onError: (error) => {
      console.error('관심 설정 변경 실패:', error);
      toast.showToast('관심 설정 변경에 실패했습니다.', {
        duration: 3000,
        position: 'top'
      });
    },
    onSettled: (_response, _error, { sourceType }) => {
      setPendingInterestRowKey(null);

      if (sourceType === 'draftProduct') {
        void queryClient.invalidateQueries({ queryKey: productsQueryKey });
        return;
      }

      void queryClient.invalidateQueries({ queryKey: productsFilesQueryKey });
    }
  });

  // --- 통합 데이터 ---
  const tableData = useMemo<UnifiedDocumentRow[]>(() => {
    const exportRows: UnifiedDocumentRow[] = exportDocuments.map((doc) => ({
      sourceType: 'export',
      id: doc.productFileId,
      document: doc,
      isInterested: Boolean(doc.isInterested),
      status: doc.status,
      documentName: parseDocumentName(doc.filePath),
      createdAt: formatCreatedAt(doc.createdAtRaw || doc.createdAt),
      createdAtTimestamp: new Date(doc.createdAtRaw || doc.createdAt).getTime() || 0
    }));

    const draftExportRows: UnifiedDocumentRow[] = draftExportDocuments.map((doc) => ({
      sourceType: 'draftExport',
      id: doc.productFileId,
      document: doc,
      isInterested: Boolean(doc.isInterested),
      status: doc.status,
      documentName: parseDocumentName(doc.filePath),
      createdAt: formatCreatedAt(doc.createdAtRaw || doc.createdAt),
      createdAtTimestamp: new Date(doc.createdAtRaw || doc.createdAt).getTime() || 0
    }));

    const draftRows: UnifiedDocumentRow[] = draftProducts.map((product) => ({
      sourceType: 'draftProduct',
      id: product.id,
      isInterested: Boolean(product.isInterested),
      status: product.generationStatus,
      documentName: product.itemName || '사업계획서 초안',
      createdAt: product.createdAt
        ? formatCreatedAt(product.createdAt)
        : product.lastUpdatedAt
        ? formatCreatedAt(product.lastUpdatedAt)
        : '-',
      createdAtTimestamp: parseSortableTimestamp(
        product.createdAt ?? product.lastUpdatedAt
      )
    }));

    return [...exportRows, ...draftExportRows, ...draftRows];
  }, [draftExportDocuments, draftProducts, exportDocuments]);

  const sorting = useMemo<SortingState>(
    () => [
      { id: 'isInterested', desc: true },
      { id: 'createdAtTimestamp', desc: true }
    ],
    []
  );

  const getSelectedKey = (doc: SelectedDocumentInfo | null): string | null => {
    if (!doc) return null;
    if (doc.type === 'export') return `export-${doc.document.productFileId}`;
    if (doc.type === 'draftExport') {
      return `draftExport-${doc.document.productFileId}`;
    }
    return `draftProduct-${doc.product.id}`;
  };

  const selectedKey = getSelectedKey(selectedDocument);

  const [isFetchingDraft, setIsFetchingDraft] = useState(false);

  const handleUploadClick = useCallback(
    async (row: UnifiedDocumentRow) => {
      const rowKey = `${row.sourceType}-${row.id}`;
      const canSelect = isSelectableRow(row);

      if (!canSelect) {
        return;
      }

      // 이미 선택된 항목이면 선택 해제
      if (selectedKey === rowKey) {
        onUpload(null);
        return;
      }

      if (row.sourceType === 'export' && row.document) {
        onUpload({ type: 'export', document: row.document });
        return;
      }

      if (row.sourceType === 'draftExport' && row.document) {
        onUpload({ type: 'draftExport', document: row.document });
        return;
      }

      if (row.sourceType === 'draftProduct') {
        // product 초안 선택 시에만 본문 텍스트를 조회한다.
        setIsFetchingDraft(true);
        try {
          const product = await getProduct(row.id);
          onUpload({
            type: 'draftProduct',
            product: {
              id: row.id,
              itemName: row.documentName,
              content: product.content || ''
            }
          });
        } catch (error) {
          console.error('초안 텍스트 조회 실패:', error);
          onUpload({
            type: 'draftProduct',
            product: { id: row.id, itemName: row.documentName, content: '' }
          });
        } finally {
          setIsFetchingDraft(false);
        }
      }
    },
    [onUpload, selectedKey]
  );

  const columns = useMemo(
    () => [
      columnHelper.accessor('isInterested', {
        id: 'isInterested',
        header: '관심',
        meta: { width: '8%', align: 'center' as const },
        cell: (info) => {
          const row = info.row.original;
          const { isInterested } = row;
          const isPending =
            toggleInterestMutation.isPending &&
            pendingInterestRowKey === `${row.sourceType}-${row.id}`;
          return (
            <Tooltip
              side="top"
              content={isInterested ? '관심 해제' : '관심 등록'}
            >
              <InterestIconButton
                type="button"
                variant="text"
                size="large"
                aria-label={`${isInterested ? '관심 해제' : '관심 등록'}: ${row.documentName}`}
                aria-busy={isPending}
                disabled={toggleInterestMutation.isPending}
                $active={isInterested}
                onClick={(event: React.MouseEvent) => {
                  event.stopPropagation();
                  toggleInterestMutation.mutate({
                    sourceType: row.sourceType,
                    documentId: row.id,
                    isInterested
                  });
                }}
              >
                <Star
                  size={16}
                  style={{
                    strokeWidth: 1.8,
                    fill: isInterested ? 'currentColor' : 'transparent'
                  }}
                />
              </InterestIconButton>
            </Tooltip>
          );
        }
      }),
      columnHelper.accessor('documentName', {
        header: '문서명',
        meta: {
          width: '68%',
          align: 'left' as const,
          headerAlign: 'center' as const
        },
        cell: (info) => {
          const row = info.row.original;
          const isProcessing =
            row.status === 'PENDING' || row.status === 'PROGRESS';
          return (
            <DocumentNameCellContent>
              {row.sourceType === 'draftProduct' ? (
                <DraftIconWrapper>
                  <FileText size={14} />
                </DraftIconWrapper>
              ) : (
                <FileIcon src="/images/icons/hwpx-icon.webp" alt="" />
              )}
              <DocumentNameMeta>
                <DocumentNameText>{info.getValue()}</DocumentNameText>
                {isProcessing ? (
                  <Badge size="small" variant="neutral">
                    생성중
                  </Badge>
                ) : null}
              </DocumentNameMeta>
            </DocumentNameCellContent>
          );
        }
      }),
      columnHelper.accessor('createdAtTimestamp', {
        id: 'createdAtTimestamp',
        header: '생성 일시',
        meta: { width: '18%', align: 'center' as const },
        cell: (info) => (
          <DateText>{info.row.original.createdAt}</DateText>
        )
      }),
      columnHelper.display({
        id: 'action',
        header: '',
        meta: { width: '6%', align: 'center' as const },
        cell: (info) => {
          const row = info.row.original;
          const canSelect = isSelectableRow(row);
          const tooltipContent = canSelect ? '선택' : getProcessingTooltip(row);
          const actionLabel = canSelect
            ? `문서 선택: ${row.documentName}`
            : `${tooltipContent}: ${row.documentName}`;

          return (
            <Tooltip side="top" content={tooltipContent}>
              <InterestIconButton
                type="button"
                variant="text"
                size="large"
                aria-label={actionLabel}
                disabled={isFetchingDraft || !canSelect}
                $active={false}
                onClick={(event: React.MouseEvent) => {
                  event.stopPropagation();
                  handleUploadClick(row);
                }}
              >
                <SquarePen size={24} style={{ strokeWidth: 1.8 }} />
              </InterestIconButton>
            </Tooltip>
          );
        }
      })
    ],
    [
      handleUploadClick,
      pendingInterestRowKey,
      toggleInterestMutation,
      isFetchingDraft
    ]
  );

  const table = useReactTable({
    data: tableData,
    columns,
    state: {
      sorting,
      pagination: { pageIndex, pageSize: PAGE_SIZE }
    },
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    autoResetPageIndex: false,
    enableSortingRemoval: false
  });

  const totalPages = table.getPageCount();
  const isEmpty = tableData.length === 0;
  const visibleColumnCount = table.getVisibleLeafColumns().length;

  return (
    <>
      <TableViewport>
        <TableFrame>
          <StyledTable>
            <TableHeader>
              {table.getHeaderGroups().map((headerGroup) => (
                <TableHeaderRow key={headerGroup.id}>
                  {headerGroup.headers.map((header) => {
                    const meta = getColumnMeta(header.column.columnDef.meta);
                    return (
                      <StyledHeaderCell
                        key={header.id}
                        $align={meta.headerAlign ?? meta.align}
                        style={{ width: meta.width }}
                      >
                        {flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                      </StyledHeaderCell>
                    );
                  })}
                </TableHeaderRow>
              ))}
            </TableHeader>
            <TableBody>
              {isEmpty ? (
                <TableBodyRow>
                  <EmptyStateCell colSpan={visibleColumnCount}>
                    <EmptyStateText>
                      기존 작성 문서가 없습니다
                    </EmptyStateText>
                  </EmptyStateCell>
                </TableBodyRow>
              ) : (
                table.getRowModel().rows.map((row) => {
                  const rowData = row.original;
                  const rowKey = `${rowData.sourceType}-${rowData.id}`;
                  const isSelected = selectedKey === rowKey;
                  const isSelectable = isSelectableRow(rowData);
                  const isRowDisabled = !isSelectable || isFetchingDraft;

                  return (
                    <SelectedTableBodyRow
                      key={row.id}
                      $selected={isSelected}
                      $disabled={!isSelectable}
                      role={isSelectable ? 'button' : undefined}
                      aria-disabled={!isSelectable}
                      tabIndex={isRowDisabled ? -1 : 0}
                      onClick={() => {
                        if (isRowDisabled) return;
                        handleUploadClick(rowData);
                      }}
                      onKeyDown={(event: React.KeyboardEvent) => {
                        if (isRowDisabled) return;
                        if (event.key === 'Enter' || event.key === ' ') {
                          event.preventDefault();
                          handleUploadClick(rowData);
                        }
                      }}
                    >
                      {row.getVisibleCells().map((cell) => {
                        const meta = getColumnMeta(cell.column.columnDef.meta);
                        return (
                          <StyledBodyCell key={cell.id} $align={meta.align}>
                            {flexRender(
                              cell.column.columnDef.cell,
                              cell.getContext()
                            )}
                          </StyledBodyCell>
                        );
                      })}
                    </SelectedTableBodyRow>
                  );
                })
              )}
            </TableBody>
          </StyledTable>
        </TableFrame>
      </TableViewport>
      {totalPages > 1 && (
        <TableFooter>
          <Pagination
            currentPage={pageIndex + 1}
            totalPage={totalPages}
            onPageChange={(page) => setPageIndex(page - 1)}
          />
        </TableFooter>
      )}
    </>
  );
}
